"use server";
import { revalidatePath } from "next/cache";
import { redirect } from "next/navigation";
import { z } from "zod";
import { requireUser } from "@/src/lib/auth/session";
import { createSupabaseAdminClient } from "@/src/lib/supabase/admin";
import { isFirebaseOperationalBackend } from "@/src/lib/firebase/platform";
import { saveFirebaseVendorProfile } from "@/src/lib/firebase/vendor-profiles";
import { FOUNDER_CATEGORY_SLUGS } from "@/src/domain/founder-categories/catalog";
import { slugify } from "@/src/lib/firebase/platform";

const schema=z.object({businessName:z.string().trim().min(2).max(160),description:z.string().trim().min(40).max(2000),publicEmail:z.string().trim().email(),phone:z.string().trim().min(7).max(30),website:z.union([z.literal(""),z.string().url()]),primaryCategory:z.string().trim().min(2).max(120),services:z.string().transform(v=>v.split("\n").map(x=>x.trim()).filter(Boolean)).pipe(z.array(z.string().min(2).max(160)).min(1).max(30)),serviceAreas:z.string().transform(v=>v.split("\n").map(x=>x.trim()).filter(Boolean)).pipe(z.array(z.string().regex(/^.+,\s*[A-Za-z]{2}$/)).min(1).max(50)),publicDisplayConsent:z.literal("on")});
const lineList=(maximum:number)=>z.string().transform(value=>value.split("\n").map(item=>item.trim()).filter(Boolean)).pipe(z.array(z.string().min(2).max(160)).max(maximum));
const optionalUrl=z.union([z.literal(""),z.string().trim().url()]);
const optionalInteger=(maximum:number)=>z.preprocess(value=>value===""||value===null?undefined:value,z.coerce.number().int().min(0).max(maximum).optional());
const firebaseSchema=z.object({
  businessName:z.string().trim().min(2).max(160),description:z.string().trim().min(40).max(2000),publicEmail:z.string().trim().email(),phone:z.string().trim().min(7).max(30),
  website:optionalUrl,googleBusinessProfileUrl:optionalUrl,primaryCategory:z.string().trim().transform(slugify).refine(value=>FOUNDER_CATEGORY_SLUGS.has(value)),
  additionalCategories:lineList(11).transform(values=>values.map(slugify)).refine(values=>values.every(value=>FOUNDER_CATEGORY_SLUGS.has(value))),services:lineList(50).refine(values=>values.length>0),
  serviceAreas:lineList(50).refine(values=>values.length>0),serviceRadiusMiles:optionalInteger(500),yearsInBusiness:optionalInteger(250),operatingHours:z.string().trim().max(1000),languages:lineList(20),customerTypes:lineList(20),
  offersFreeEstimates:z.boolean(),offersFinancing:z.boolean(),emergencyService:z.boolean(),licenseApplies:z.boolean(),licenseNumber:z.string().trim().max(160),licenseJurisdiction:z.string().trim().max(160),
  insuranceStatus:z.enum(["unknown","insured","not_insured","expired"]),connectMemberBenefitEnabled:z.boolean(),connectMemberBenefitTitle:z.string().trim().max(160),connectMemberBenefitDescription:z.string().trim().max(1000),
  connectMemberBenefitType:z.string().trim().max(100),connectMemberBenefitTerms:z.string().trim().max(1000),publicDisplayConsent:z.boolean(),
}).superRefine((value,context)=>{if(value.licenseApplies&&(!value.licenseNumber||!value.licenseJurisdiction))context.addIssue({code:"custom",message:"License number and jurisdiction are required."});if(value.connectMemberBenefitEnabled&&(!value.connectMemberBenefitTitle||value.connectMemberBenefitDescription.length<10||!value.connectMemberBenefitType))context.addIssue({code:"custom",message:"Complete the Connect Member Benefit details."});});
export async function saveVendorProfile(formData:FormData){
  const user=await requireUser();const org=user.memberships.find(x=>x.organizationType==="vendor"&&["owner","admin"].includes(x.role));if(!org)redirect("/vendor/profile?result=unauthorized");
  if(isFirebaseOperationalBackend()){
    const parsed=firebaseSchema.safeParse({businessName:formData.get("businessName"),description:formData.get("description"),publicEmail:formData.get("publicEmail"),phone:formData.get("phone"),website:formData.get("website")??"",googleBusinessProfileUrl:formData.get("googleBusinessProfileUrl")??"",primaryCategory:formData.get("primaryCategory"),additionalCategories:formData.get("additionalCategories")??"",services:formData.get("services")??"",serviceAreas:formData.get("serviceAreas")??"",serviceRadiusMiles:formData.get("serviceRadiusMiles"),yearsInBusiness:formData.get("yearsInBusiness"),operatingHours:formData.get("operatingHours")??"",languages:formData.get("languages")??"",customerTypes:formData.get("customerTypes")??"",offersFreeEstimates:formData.get("offersFreeEstimates")==="on",offersFinancing:formData.get("offersFinancing")==="on",emergencyService:formData.get("emergencyService")==="on",licenseApplies:formData.get("licenseApplies")==="on",licenseNumber:formData.get("licenseNumber")??"",licenseJurisdiction:formData.get("licenseJurisdiction")??"",insuranceStatus:formData.get("insuranceStatus"),connectMemberBenefitEnabled:formData.get("connectMemberBenefitEnabled")==="on",connectMemberBenefitTitle:formData.get("connectMemberBenefitTitle")??"",connectMemberBenefitDescription:formData.get("connectMemberBenefitDescription")??"",connectMemberBenefitType:formData.get("connectMemberBenefitType")??"",connectMemberBenefitTerms:formData.get("connectMemberBenefitTerms")??"",publicDisplayConsent:formData.get("publicDisplayConsent")==="on"});
    if(!parsed.success)redirect("/vendor/profile?result=invalid");const value=parsed.data;
    try{await saveFirebaseVendorProfile({user,organizationId:org.organizationId,businessName:value.businessName,description:value.description,publicEmail:value.publicEmail,publicPhone:value.phone,websiteUrl:value.website||null,googleBusinessProfileUrl:value.googleBusinessProfileUrl||null,primaryCategorySlug:value.primaryCategory,additionalCategorySlugs:value.additionalCategories,services:value.services,serviceAreas:value.serviceAreas,serviceRadiusMiles:value.serviceRadiusMiles??null,operatingHours:value.operatingHours||null,languages:value.languages,yearsInBusiness:value.yearsInBusiness??null,customerTypes:value.customerTypes,offersFreeEstimates:value.offersFreeEstimates,offersFinancing:value.offersFinancing,emergencyService:value.emergencyService,license:{applies:value.licenseApplies,number:value.licenseNumber||null,jurisdiction:value.licenseJurisdiction||null},insurance:{status:value.insuranceStatus},connectMemberBenefit:{enabled:value.connectMemberBenefitEnabled,title:value.connectMemberBenefitTitle||null,description:value.connectMemberBenefitDescription||null,type:value.connectMemberBenefitType||null,terms:value.connectMemberBenefitTerms||null},publicDisplayConsent:value.publicDisplayConsent});}catch{redirect("/vendor/profile?result=invalid");}
    revalidatePath("/vendor");revalidatePath("/vendor/profile");revalidatePath("/marketplace");redirect("/vendor/profile?result=saved");
  }
  const parsed=schema.safeParse(Object.fromEntries(formData));if(!parsed.success)redirect("/vendor/profile?result=invalid");
  const admin=createSupabaseAdminClient();const {error}=await admin.rpc("save_vendor_profile_onboarding",{target_vendor_organization_id:org.organizationId,target_user_id:user.id,target_payload:{business_name:parsed.data.businessName,description:parsed.data.description,public_email:parsed.data.publicEmail,phone:parsed.data.phone,website_url:parsed.data.website,primary_category:parsed.data.primaryCategory,services:parsed.data.services,service_areas:parsed.data.serviceAreas,public_display_consent:true}});
  if(error)redirect("/vendor/profile?result=error");revalidatePath("/vendor");revalidatePath("/vendor/profile");revalidatePath("/marketplace");redirect("/vendor/profile?result=saved");
}
